import{_ as e,o as a,c as t,a2 as i}from"./chunks/framework.D0_YsCyK.js";const p=JSON.parse('{"title":"导入节点","description":"","frontmatter":{},"headers":[],"relativePath":"guide/import.md","filePath":"guide/import.md","lastUpdated":1792712240000}'),l={name:"guide/import.md"};function s(r,o,d,c,n,h){return a(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="导入节点" tabindex="-1">导入节点 <a class="header-anchor" href="#导入节点" aria-label="Permalink to &quot;导入节点&quot;">​</a></h1><p>在 <strong>落地</strong> 页点击 <strong>导入</strong>，可以把不是面板部署的节点（脚本搭的、没装 agent 的机器、机场节点）加进来，用来对接中转和加入订阅。转换规则参考 Sub-Store：所有格式先转成 Mihomo（Clash Meta）节点格式保存，再按订阅格式输出，参数不会丢失。</p><h2 id="支持的输入" tabindex="-1">支持的输入 <a class="header-anchor" href="#支持的输入" aria-label="Permalink to &quot;支持的输入&quot;">​</a></h2><ul><li>分享链接（每行一个）：<code>ss://</code>（含 obfs / v2ray-plugin / shadow-tls 插件）、<code>vmess://</code>（v2rayN 格式）、<code>vless://</code>（含 Reality、WS、gRPC、H2、XHTTP）、<code>trojan://</code>、<code>hysteria2://</code> / <code>hy2://</code>、<code>tuic://</code>、<code>anytls://</code>、<code>socks5://</code></li><li>base64 订阅内容</li><li>Clash / Mihomo 配置（读取 <code>proxies</code>）</li><li>sing-box 配置（读取 <code>outbounds</code>）</li><li>Surge / Loon 节点行，例如 <code>名称 = snell, 1.2.3.4, 6160, psk=..., version=4</code></li><li>订阅地址（<code>https://...</code>）：面板服务器以 <code>flmx-panel/1.0</code> 为 User-Agent 去下载（IMP-002：手册曾写&quot;以 Mihomo 的身份&quot;，与实际不符，已更正），拿到的通常是参数最完整的 Clash 配置。打开 <strong>定时同步</strong>（默认打开）会存成 <a href="./subscription#订阅源">订阅源</a>，按时更新；关掉则只导入一次。注意：依赖 UA 嗅探返回差异化内容的订阅源，可能返回参数不完整的内容</li></ul><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><ul><li>暂不支持 WireGuard、SSR、Hysteria v1 等类型，导入时会逐条提示</li><li>Shadowsocks 类条目必须带密码：1.3.4 起，无密码（或加密方式为空）的 SS / SSU / TAP 配置在节点侧会<strong>直接报错、服务起不来</strong>，不再像旧版本那样静默以明文运行。导入或手工编写 gost 配置、手工链里有这类条目时，请先补上密码再下发；报错信息会明确指出缺 auth。面板正常创建的 SS 入站与 SS 链恒带密码，不受影响</li><li>节点地址不能是本机地址（<code>127.0.0.1</code> 等 loopback 地址或 <code>0.0.0.0</code>），导入时会被逐条拒绝并提示「地址不能是本机或 0.0.0.0」</li><li>保留段与组播段地址同样拒绝：云元数据地址、保留地址段（如 <code>0.x.x.x</code>）与组播地址（如 <code>224.0.0.0/4</code> 段）在导入与连通性检测时同样会被拒绝；公网、私网与运营商 NAT（CGNAT）地址不受影响</li><li>Shadowsocks 2022（<code>2022-blake3-*</code>）节点的密钥会校验格式：base64 解码后须为 16/32 字节，SIP023 冒号多段密钥按段逐段校验；不合规的单条节点会被拒绝并提示原因，其余节点照常导入。SIP023 多段合法节点在 sing-box 订阅中会逐段规范化为带填充的标准 base64 后下发（解码出的密钥字节不变；sing-box 1.11 / 1.12 / 1.14 均已实测可正常解析多段密钥）。此前已导入的异常节点（任一段密钥不合规）在 sing-box 订阅渲染时仍会被略过（Clash 等其他格式仍原样输出）</li><li>经中转连接时，原节点用域名连接的，会自动把域名保留为 TLS SNI 和 WebSocket Host；Hysteria2 端口跳跃只在直连线路上保留</li><li>面板不会部署、修改这些节点，也没有流量统计、白名单、换密钥等功能</li><li>原节点的地址或参数变了，点击该节点 → <strong>编辑</strong>，修改地址或粘贴新的链接替换参数，相关中转会自动指向新地址</li><li>勾选“订阅里只保留中转线路”后，订阅和分享中不再包含直连线路（该节点没有中转时就不会出现在订阅里）</li><li>删除只会删除面板里的记录和相关中转，不影响原服务器</li><li>同一个地址和端口在导入节点之间不会重复导入（与面板自建入站同地址同端口不算重复，自建与导入可以共存）</li><li>单次导入上限 500 个节点（IMP-008）：<strong>手动导入</strong>（粘贴链接/内容）超过 500 个会直接拒绝，请分批导入；<strong>订阅源同步</strong>超过 500 个会只保留前 500 个并给出提示</li></ul><h2 id="连通性检测" tabindex="-1">连通性检测 <a class="header-anchor" href="#连通性检测" aria-label="Permalink to &quot;连通性检测&quot;">​</a></h2><p>面板服务器每 3 分钟会连一次所有导入的节点，落地页上方的 <strong>检测</strong> 按钮可以马上测一遍：</p><ul><li>连得上：绿点，后面显示延迟（例如 <code>· 85 ms</code>）</li><li>连不上：红点，并显示原因（连接超时、域名解析失败、无法连接）</li></ul><p>检测是从 <strong>面板服务器</strong> 发起的 TCP 连接，只能作为参考：面板连不上不代表中转机也连不上，反之亦然。Hysteria2、TUIC 只用 UDP，无法这样检测，不显示状态。开启 <a href="./notify">通知</a> 后，导入节点连续两次连不上会推送提醒。</p><h2 id="对接中转" tabindex="-1">对接中转 <a class="header-anchor" href="#对接中转" aria-label="Permalink to &quot;对接中转&quot;">​</a></h2><p>导入后的节点和面板部署的入站一样：点击节点 → <strong>中转</strong> → 选择隧道即可，端口转发和隧道转发（包括经 IX 的多跳）都可以用。见 <a href="./relay">对接中转</a>。</p><h2 id="订阅源地址安全策略" tabindex="-1">订阅源地址安全策略 <a class="header-anchor" href="#订阅源地址安全策略" aria-label="Permalink to &quot;订阅源地址安全策略&quot;">​</a></h2><p>订阅源 URL 默认仅支持 <strong>https 公网地址</strong>。如需使用 http 或内网地址，需管理员显式配置：</p><ul><li><code>FLMX_FETCH_ALLOW_PRIVATE_NETWORKS=true</code>：放行所有私网地址（不推荐）</li><li><code>FLMX_FETCH_PRIVATE_ALLOWLIST=192.168.0.0/16,10.0.0.0/8</code>：仅放行指定 CIDR（推荐）</li></ul><p><strong>风险说明</strong>：放行私网地址会允许面板服务器访问内网资源。请确保订阅源可信，并注意：</p><ul><li>云元数据地址（<code>169.254.169.254</code>）在任何配置下都被拒绝</li><li>私网放行会记录审计日志</li><li>公网 http 在任何配置下都被拒绝（必须使用 https）</li></ul>',17)])])}const g=e(l,[["render",s]]);export{p as __pageData,g as default};
